      "customfield_10231": {
        "value": {
          "type": "doc",
          "version": 1,
          "content": [
            {
              "type": "paragraph",
              "content": [
                {
                  "type": "text",
                  "text": "Core component",
                  "marks": [
                    {
                      "type": "strong"
                    }
                  ]
                }
              ],
              "attrs": {
                "localId": "61350d9fe561"
              }
            },
            {
              "type": "orderedList",
              "attrs": {
                "order": 1,
                "localId": "d2ea1e1fcf73"
              },
              "content": [
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "8d7064f163eb"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given a product is passed to the card component, when it renders, then the primary product image is always displayed regardless of variation."
                        }
                      ],
                      "attrs": {
                        "localId": "5d95c4069fe0"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "1d7aa3ba3390"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given the component is built as a PWA component, when imported into any page surface, then it renders correctly without page-specific logic embedded in the component itself."
                        }
                      ],
                      "attrs": {
                        "localId": "2e3f0b45d6b7"
                      }
                    }
                  ]
                }
              ]
            },
            {
              "type": "paragraph",
              "content": [
                {
                  "type": "text",
                  "text": "PLP variation",
                  "marks": [
                    {
                      "type": "strong"
                    }
                  ]
                }
              ],
              "attrs": {
                "localId": "e710a12ad55e"
              }
            },
            {
              "type": "orderedList",
              "attrs": {
                "order": 1,
                "localId": "2e80c9ca975d"
              },
              "content": [
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "f2b28acc505d"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given the card renders on PLP, when it is in the default state, then the image, name, badge, price (incl. was/now), and cart icon are visible."
                        }
                      ],
                      "attrs": {
                        "localId": "e710a12ad55e"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "049e118856af"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given the card renders on PLP, when on desktop and the user hovers, then the size selector becomes visible and the price disappears and the tile image switches from the item/flat photo to the model photo."
                        }
                      ],
                      "attrs": {
                        "localId": "144e18aa195c"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "f2b28acc505d"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given the card renders on PLP, when on desktop and the user hovers, then the arrows appear for the shopper to click through the product images."
                        }
                      ],
                      "attrs": {
                        "localId": "fa84ee7f18e2"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "f2b28acc505d"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given the card renders on PLP, when on mobile, then the size selector is not displayed."
                        }
                      ],
                      "attrs": {
                        "localId": "e710a12ad55e"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "f2b28acc505d"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given a product is out of stock, when the card renders, then the cart is greyed out and a notify me link appears on hover instead of price."
                        }
                      ],
                      "attrs": {
                        "localId": "e710a12ad55e"
                      }
                    }
                  ]
                }
              ]
            },
            {
              "type": "paragraph",
              "content": [
                {
                  "type": "text",
                  "text": "Home page variation",
                  "marks": [
                    {
                      "type": "strong"
                    }
                  ]
                }
              ],
              "attrs": {
                "localId": "0220f6026889"
              }
            },
            {
              "type": "orderedList",
              "attrs": {
                "order": 1,
                "localId": "4ab642451699"
              },
              "content": [
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "83ffaad90855"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given the card renders on home page, when it is in the default state, then the image and name are displayed."
                        }
                      ],
                      "attrs": {
                        "localId": "7fb4d575ac68"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "f2b28acc505d"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given the card renders on home page, when on desktop and the user hovers, then the arrows appear for the shopper to click through the product images."
                        }
                      ],
                      "attrs": {
                        "localId": "666499e3466d"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "f2b28acc505d"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given the card renders on home page, when on desktop and the user hovers, then the price (incl. was/now) appears."
                        }
                      ],
                      "attrs": {
                        "localId": "0c3594a69fe9"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "f2b28acc505d"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given the card renders on home page, when on mobile, then the user only sees the image and name."
                        }
                      ],
                      "attrs": {
                        "localId": "8c6847f73d28"
                      }
                    }
                  ]
                }
              ]
            },
            {
              "type": "paragraph",
              "content": [
                {
                  "type": "text",
                  "text": "Wishlist variation",
                  "marks": [
                    {
                      "type": "strong"
                    }
                  ]
                }
              ],
              "attrs": {
                "localId": "ba1e576e6dc7"
              }
            },
            {
              "type": "orderedList",
              "attrs": {
                "order": 1,
                "localId": "4613391431ac"
              },
              "content": [
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "6bbf74a9268d"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given the card renders on the wishlist, when it is in the default state, then the image, cart icon, name, colour, size, badge, and price (incl. was/now) are displayed."
                        }
                      ],
                      "attrs": {
                        "localId": "a299eaa7d45f"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "be1c2e1218ae"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given the card renders on the wishlist, then there is a remove ('x') cta on the top right."
                        }
                      ],
                      "attrs": {
                        "localId": "d4c77755684e"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "15285bbbf379"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given the card renders on wishlist, when on desktop and the user hovers, then the tile image switches from the item/flat photo to the model photo."
                        }
                      ],
                      "attrs": {
                        "localId": "68b5d2534eb5"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "48b8dd42b310"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given the card renders on wishlist, when on desktop and the user hovers, then the arrows appear for the shopper to click through the product images."
                        }
                      ],
                      "attrs": {
                        "localId": "b21541493798"
                      }
                    }
                  ]
                }
              ]
            },
            {
              "type": "paragraph",
              "content": [
                {
                  "type": "text",
                  "text": "Recently Viewed Full History variation (same behavior as PLP card)",
                  "marks": [
                    {
                      "type": "strong"
                    }
                  ]
                }
              ],
              "attrs": {
                "localId": "f3ea71a1666c"
              }
            },
            {
              "type": "orderedList",
              "attrs": {
                "order": 1,
                "localId": "1fbdb1deee0a"
              },
              "content": [
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "c9829b773138"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given the card renders on the View Full History Page, when it is in the default state, then the image, name, badge, price (incl. was/now), and cart icon are visible."
                        }
                      ],
                      "attrs": {
                        "localId": "d04397579418"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "000425b7fbc9"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given the card renders on View Full History Page, when on desktop and the user hovers, then the size selector becomes visible and the price disappears and the tile image switches from the item/flat photo to the model photo."
                        }
                      ],
                      "attrs": {
                        "localId": "4c818485e292"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "01c89b02def7"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given the card renders on View Full History Page, when on desktop and the user hovers, then the arrows appear for the shopper to click through the product images."
                        }
                      ],
                      "attrs": {
                        "localId": "f8d6a4605b45"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "ac2de905f4e7"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given the card renders on View Full History Page, when on mobile, then the size selector is not displayed."
                        }
                      ],
                      "attrs": {
                        "localId": "d5e3476fa7c4"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "03ef0a4e8a71"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given a product is out of stock, when the card renders, then the cart is greyed out and a notify me link appears on hover instead of price."
                        }
                      ],
                      "attrs": {
                        "localId": "d1aaf2929c1a"
                      }
                    }
                  ]
                }
              ]
            },
            {
              "type": "paragraph",
              "content": [
                {
                  "type": "text",
                  "text": "Variation extensibility",
                  "marks": [
                    {
                      "type": "strong"
                    }
                  ]
                }
              ],
              "attrs": {
                "localId": "09728005e784"
