69	      notifyMeButton: {},
70	      // ZimmProductPrice.
71	      container: {},
72	      wasPrice: {},
73	      nowPrice: {},
74	      // ZimmSizeChipGroup.
75	      radiogroup: {},
76	      oneSize: {},
77	      // ZimmSizeChip.
78	      chip: {},
79	    }),
80	  };
81	});
82	
83	// ZimmIcon (used by ZimmProductCardContent's bag button) and the icons barrel (used by
84	// ZimmProductCardMedia's close/arrow buttons): known Vitest SVG side-effect issue documented in
85	// .claude/rules/testing.md's "Known gap: ZimmIcon throws under Vitest". Mocked at the same
86	// resolved module each consumer imports — both consumers sit at the same depth below `ui-kits/`
87	// as this test file, so the relative specifiers are identical to what
88	// zimmProductCardContent/index.test.tsx and zimmProductCardMedia/index.test.tsx use themselves.
89	vi.mock('../../atoms/zimmIcon', () => ({ ZimmIcon: () => null }));
90	vi.mock('../../../icons', () => ({
91	  ChevronLeftIcon: () => null,
92	  ChevronRightIcon: () => null,
93	  CloseIcon: () => null,
