95	
96	const wrap = (ui: React.ReactElement) =>
97	  render(
98	    <MemoryRouter>
99	      <IntlProvider locale="en" defaultLocale="en">
100	        {ui}
101	      </IntlProvider>
102	    </MemoryRouter>,
103	  );
104	
105	const PRIMARY: ZimmProductCardImage = { src: 'primary.jpg', alt: 'Zimmermann dress, front' };
106	const GALLERY: ZimmProductCardImage[] = [
107	  { src: 'g1.jpg', alt: 'Zimmermann dress, front' },
108	  { src: 'g2.jpg', alt: 'Zimmermann dress, side' },
109	  { src: 'g3.jpg', alt: 'Zimmermann dress, back' },
110	];
111	
112	const SIZES = [
113	  { value: 'xs', label: 'XS' },
114	  { value: 's', label: 'S' },
115	];
116	
117	/**
118	 * Module-scope (not describe-block-local) so both the "real recipe assertions" describe block
119	 * below AND the Fix 1 / Fix 2 (Scorer rework round 1) DOM-level proof blocks further down can
120	 * share one definition rather than each hand-duplicating the same literal selector strings.
121	 */
122	const HOVER_CAPABLE_QUERY = '@media (hover: hover) and (pointer: fine)';
123	const STRETCH_KEY = '[data-card-slot="content"] a::after';
124	const CLOSE_LIFT_KEY = '[data-card-slot="close"]';
125	const CAROUSEL_LIFT_KEY = '[data-card-slot="carousel"] button';
126	const CONTENT_LIFT_KEY = '[data-card-slot="content"] button';
127	const PRICE_KEY = '[data-card-slot="content"] [data-card-slot="price"]';
128	const SIZE_CHIPS_KEY = '[data-card-slot="content"] [data-card-slot="sizeChips"]';
129	const HOVER_PRICE_KEY = `&:hover ${PRICE_KEY}`;
130	const HOVER_SIZE_CHIPS_KEY = `&:hover ${SIZE_CHIPS_KEY}`;
131	// Fix 2 (Scorer rework round 1): the keyboard-reachable equivalent of each hover-reveal rule
132	// above — see this file's own docblock note on the compound-selector vs separate-key idiom
133	// question, resolved by reading zimmSearchInput.css.ts and globalStyles.ts's zimmFormRow/
134	// zimmFormRowInverse: both use a separate sibling key (`_focusWithin` alongside `_hover`), never
135	// a comma-joined compound selector. This file already uses raw selector strings (not Chakra's
136	// `_hover`/`_focusWithin` shorthand props) because the hover rules need a descendant-combinator
137	// path baked into the selector itself, so the equivalent here is a separate `'&:focus-within ...'`
138	// string key alongside the existing `'&:hover ...'` key, not a merged `'&:hover, &:focus-within ...'`
139	// selector.
140	const FOCUS_WITHIN_PRICE_KEY = `&:focus-within ${PRICE_KEY}`;
141	const FOCUS_WITHIN_SIZE_CHIPS_KEY = `&:focus-within ${SIZE_CHIPS_KEY}`;
142	
143	/** Mocks the scroll container's native `scrollTo` (absent under jsdom), same technique as
144	 *  zimmProductCardMedia/index.test.tsx's own mockScrollTo. */
145	const mockScrollTo = (): ReturnType<typeof vi.fn> => {
146	  const scrollContainer = screen.getByTestId('card-media-scroll');
147	  const scrollTo = vi.fn();
148	  scrollContainer.scrollTo = scrollTo;
149	  return scrollTo;
150	};
151	
152	/**
153	 * A complete, valid props object for a given variation — narrows on `variation` with a plain
154	 * `switch` (fine here: the "no switch/if on props.variation" constraint applies only to
155	 * index.tsx's own render body, not to test fixtures).
156	 *
157	 * Overloaded (not a single `(variation) => ZimmProductCardProps` signature) so a call site that
158	 * passes a literal (`buildCardProps('plp')`) gets back the properly *narrow* per-variation type,
159	 * not the full union — needed so a test can then add a variation-specific prop on top (e.g.
160	 * `{...buildCardProps('wishlist')} onRemove={fn}`) without TypeScript rejecting it as "not
161	 * present on every union member." A `test.each` call site passing a runtime (non-literal)
162	 * `variation` still resolves to the final, general overload below.
163	 */
164	function buildCardProps(variation: 'plp'): ZimmProductCardBaseProps & ZimmProductCardPlpVariation;
165	function buildCardProps(variation: 'home'): ZimmProductCardBaseProps & ZimmProductCardHomeVariation;
166	function buildCardProps(variation: 'wishlist'): ZimmProductCardBaseProps & ZimmProductCardWishlistVariation;
167	function buildCardProps(variation: ZimmProductCardProps['variation']): ZimmProductCardProps;
168	function buildCardProps(variation: ZimmProductCardProps['variation']): ZimmProductCardProps {
169	  const base = {
170	    id: 'p1',
171	    href: '/product/1',
172	    name: 'Natura Dress',
173	    headingLevel: 'h3' as const,
174	    primaryImage: PRIMARY,
175	  };
176	  switch (variation) {
177	    case 'wishlist':
178	      return { ...base, variation, colour: 'Ivory', size: 'M', onRemove: vi.fn() };
179	    case 'home':
180	      return { ...base, variation };
181	    case 'plp':
182	      return { ...base, variation };
183	    default:
184	      // Exhaustiveness guard — a new union member without a matching branch here fails `tsc`,
185	      // not silently falls through to a wrong variation's shape.
186	      return ((): never => {
187	        throw new Error(`buildCardProps: unhandled variation ${JSON.stringify(variation)}`);
188	      })();
189	  }
190	}
191	
192	describe('ZimmProductCardProps — discriminated union is enforced at compile time', () => {
193	  // Both cases below are type-only proof: `@ts-expect-error` makes `tsc --noEmit` fail this file
194	  // if the offending line does NOT produce a compile error (an "Unused '@ts-expect-error'
195	  // directive" diagnostic) — so these only stay green while the union genuinely rejects the
196	  // invalid shape. The runtime assertion is trivial; TypeScript strips the annotation either way,
197	  // so the object still constructs and runs at test time regardless of what `tsc` says about it.
198	  test('wishlist variation requires onRemove, colour and size (type-only)', () => {
199	    // @ts-expect-error — wishlist requires onRemove, colour and size; none are supplied here.
200	    const invalid: ZimmProductCardProps = {
201	      id: 'p1',
202	      href: '/product/1',
203	      name: 'Dress',
204	      headingLevel: 'h3',
205	      primaryImage: PRIMARY,
206	      variation: 'wishlist',
207	    };
208	    expect(invalid).toBeDefined();
209	  });
210	
211	  test('home variation does not accept onRemove (type-only)', () => {
212	    // Assigned to the narrow per-variation intersection, not the `ZimmProductCardProps` union
213	    // alias: TypeScript's excess-property check on a *union* target only flags a property as
214	    // excess when it is unknown to EVERY member, so `onRemove` (valid on the wishlist member)
215	    // would silently pass here even under `variation: 'home'` if assigned to the union type
216	    // directly — confirmed empirically while building this test (an earlier version of this
217	    // exact case, assigned to `ZimmProductCardProps`, produced an "unused @ts-expect-error"
218	    // compile error because of this). The narrow intersection has no such escape hatch: it is a
219	    // plain object type with no `onRemove` key anywhere, so the excess property is genuinely
220	    // unknown and TypeScript reports it.
221	    //
222	    // The directive sits directly above the `onRemove` line, not the `const invalid = {` line
223	    // above it: TS anchors this specific "object literal may only specify known properties"
224	    // diagnostic to the offending property's own line, and `@ts-expect-error` only suppresses
225	    // (and only counts as "used" for) a diagnostic reported on the *immediate next* line.
226	    const invalid: ZimmProductCardBaseProps & ZimmProductCardHomeVariation = {
227	      id: 'p2',
228	      href: '/product/1',
229	      name: 'Dress',
230	      headingLevel: 'h3',
231	      primaryImage: PRIMARY,
232	      variation: 'home',
233	      // @ts-expect-error — onRemove does not exist on the home variation's own shape.
234	      onRemove: () => {},
235	    };
236	    expect(invalid).toBeDefined();
237	  });
238	});
239	
240	describe('ZimmProductCard — AC1: primary image renders for every variation x availability', () => {
241	  const cases: Array<[ZimmProductCardProps['variation'], boolean]> = [
242	    ['plp', false],
243	    ['plp', true],
244	    ['home', false],
245	    ['home', true],
246	    ['wishlist', false],
247	    ['wishlist', true],
248	  ];
249	
250	  test.each(cases)('variation=%s, isUnavailable=%s renders the primary image', (variation, isUnavailable) => {
251	    wrap(<ZimmProductCard {...buildCardProps(variation)} isUnavailable={isUnavailable} />);
252	    const img = screen.getByRole('img', { name: PRIMARY.alt });
253	    expect(img).toHaveAttribute('src', PRIMARY.src);
254	  });
255	});
256	
257	describe('ZimmProductCard — exactly one real anchor regardless of variation', () => {
258	  test.each(['plp', 'home', 'wishlist'] as const)('variation=%s renders exactly one <a>', (variation) => {
259	    wrap(<ZimmProductCard {...buildCardProps(variation)} />);
260	    const links = screen.getAllByRole('link');
261	    expect(links).toHaveLength(1);
262	    expect(links[0]).toHaveAttribute('href', '/product/1');
263	  });
264	});
265	
266	/**
267	 * KNOWN LIMITATION — read before trusting these as proof of the real z-index layering.
268	 *
269	 * Every test below fires a click/keydown directly on the target control's own DOM node via
270	 * Testing Library. That proves the CALLBACK WIRING is correct: the right element calls the right
271	 * handler when it is actually interacted with. It does NOT prove that a real mouse click at that
272	 * screen position, in an actual browser, would land on that control rather than on the invisible
273	 * stretched-link `::after` overlay sitting over the whole card — jsdom performs no real layout,
274	 * paint, or hit-testing (no CSS cascade resolution, no stacking-context/z-index comparison, no
275	 * geometry at all); `fireEvent`/`user-event` dispatch straight to the node you name, bypassing
276	 * whatever a browser's hit-testing algorithm would actually resolve at that (x, y). The
277	 * `zimmProductCard.css.ts` recipe assertions further below prove the CSS this organism emits has
278	 * the right `position`/`z-index` values (verified by literally compiling it through this
279	 * project's real Stylis — see that describe block) — but going from "the right CSS values exist"
280	 * to "a real browser click lands on the right element" is exactly the gap a real-browser
281	 * (Playwright or manual) check is for. Treat this whole file as necessary, not sufficient, proof.
282	 */
