351	/**
352	 * Real-recipe assertions — bypasses the useMultiStyleConfig mock entirely, same technique as
353	 * zimmProductCardMedia/index.test.tsx's "Fix 1" block and
354	 * zimmProductCardContent/index.test.tsx's own real-recipe block. The component-level tests above
355	 * all render through the flat mock at the top of this file, which cannot see whether the real
356	 * recipe ever regresses the hover-reveal media query, the stretched-link overlay, or the z-index
357	 * lift on the interactive controls.
358	 *
359	 * These string keys were independently verified by compiling this exact recipe shape through
360	 * this project's own installed Stylis (v4.2.0 — the same engine Emotion/Chakra invoke at
361	 * runtime): the plain descendant selectors below resolve exactly as written, scoped under this
362	 * recipe's own generated class, with no comma-list scoping surprises.
363	 */
364	describe('ZimmProductCard — real recipe assertions (bypasses the useMultiStyleConfig mock)', () => {
365	  test('the stretched-link overlay is unconditional, absolutely positioned, and carries no z-index of its own', () => {
366	    const style = ZimmProductCardRecipe.baseStyle({});
367	    const root = style.root as Record<string, unknown>;
368	    const after = root[STRETCH_KEY] as Record<string, unknown>;
369	    expect(after.position).toBe('absolute');
370	    expect(after.inset).toBe(0);
371	    expect(Object.prototype.hasOwnProperty.call(after, 'zIndex')).toBe(false);
372	  });
373	
374	  test('the carousel and content-button lift selectors use position:relative + zIndex:1 — neither element is positioned by its own component recipe', () => {
375	    const style = ZimmProductCardRecipe.baseStyle({});
376	    const root = style.root as Record<string, unknown>;
377	    for (const key of [CAROUSEL_LIFT_KEY, CONTENT_LIFT_KEY]) {
378	      const rule = root[key] as Record<string, unknown>;
379	      expect(rule.position).toBe('relative');
380	      expect(rule.zIndex).toBe(1);
381	    }
382	  });
383	
384	  /**
385	   * Fix 1 (Scorer rework round 1): the close-button lift rule used to also set
386	   * `position: 'relative'`, which is what an earlier version of this exact test asserted for all
387	   * three lift keys together. That was proven wrong by rendering the real composed tree: Media's
388	   * own `close` recipe part already sets `position: 'absolute', top: 0, right: 0` on this exact
389	   * element, and this rule's `.css-root [data-card-slot="close"]` descendant+attribute selector
390	   * has higher specificity than Media's own single-class rule — so `position: 'relative'` here
391	   * WON the cascade and knocked the remove button out of its pinned top-right corner into normal
392	   * flow. The element is already positioned (by Media's own recipe), which is all `zIndex` needs
393	   * to take effect — a competing `position` value here was never necessary. See the DOM-level
394	   * proof below (real recipes composed through the real `chakra` factory + `getComputedStyle`)
395	   * for confirmation the fix actually restores the pinned position, not just that this key's shape
396	   * looks right in isolation.
397	   */
398	  test('the close lift selector sets only zIndex, never position — the element is already positioned by ZimmProductCardMedia’s own recipe', () => {
399	    const style = ZimmProductCardRecipe.baseStyle({});
400	    const root = style.root as Record<string, unknown>;
401	    const closeLift = root[CLOSE_LIFT_KEY] as Record<string, unknown>;
402	    expect(closeLift.zIndex).toBe(1);
403	    expect(Object.prototype.hasOwnProperty.call(closeLift, 'position')).toBe(false);
404	  });
405	
406	  test('root itself establishes the positioned ancestor the stretched-link overlay resolves against', () => {
407	    const style = ZimmProductCardRecipe.baseStyle({});
408	    expect((style.root as Record<string, unknown>).position).toBe('relative');
409	  });
410	
411	  test('home (hoverRevealsPrice): price is hidden by default and revealed on hover AND on focus-within, no size-selector rule at all', () => {
412	    const style = ZimmProductCardRecipe.baseStyle({ hoverRevealsPrice: true });
413	    const root = style.root as Record<string, unknown>;
414	    expect((root[PRICE_KEY] as Record<string, unknown>).display).toBe('none');
415	    const hoverBlock = root[HOVER_CAPABLE_QUERY] as Record<string, unknown>;
416	    expect((hoverBlock[HOVER_PRICE_KEY] as Record<string, unknown>).display).toBe('block');
417	    // Fix 2 (Scorer rework round 1): the focus-within equivalent must reveal identically, so a
418	    // keyboard-only user tabbing through the card sees the same state a mouse-hover would.
419	    expect((hoverBlock[FOCUS_WITHIN_PRICE_KEY] as Record<string, unknown>).display).toBe('block');
420	    expect(root[SIZE_CHIPS_KEY]).toBeUndefined();
421	    expect(hoverBlock[HOVER_SIZE_CHIPS_KEY]).toBeUndefined();
422	    expect(hoverBlock[FOCUS_WITHIN_SIZE_CHIPS_KEY]).toBeUndefined();
423	  });
