426	    const style = ZimmProductCardRecipe.baseStyle({ hoverHidesPrice: true, hoverRevealsSizeSelector: true });
427	    const root = style.root as Record<string, unknown>;
428	    // No unconditional price rule — Content's own natural rendering already shows it by default.
429	    expect(root[PRICE_KEY]).toBeUndefined();
430	    expect((root[SIZE_CHIPS_KEY] as Record<string, unknown>).display).toBe('none');
431	    const hoverBlock = root[HOVER_CAPABLE_QUERY] as Record<string, unknown>;
432	    expect((hoverBlock[HOVER_PRICE_KEY] as Record<string, unknown>).display).toBe('none');
433	    expect((hoverBlock[HOVER_SIZE_CHIPS_KEY] as Record<string, unknown>).display).toBe('block');
434	    // Fix 2 (Scorer rework round 1): focus-within must swap identically to hover — a keyboard
435	    // user tabbing into the card (e.g. onto the bag button or a size chip) sees the size-selector
436	    // in place of the price, the same revealed state a mouse-hover produces, not a silently
437	    // unreachable one.
438	    expect((hoverBlock[FOCUS_WITHIN_PRICE_KEY] as Record<string, unknown>).display).toBe('none');
439	    expect((hoverBlock[FOCUS_WITHIN_SIZE_CHIPS_KEY] as Record<string, unknown>).display).toBe('block');
440	  });
