442	  test('with every hover flag false/absent, no hover-reveal or focus-within-reveal rule is emitted at all — a touch/no-hover pointer keeps the natural default permanently', () => {
443	    const style = ZimmProductCardRecipe.baseStyle({});
444	    const root = style.root as Record<string, unknown>;
445	    expect(root[PRICE_KEY]).toBeUndefined();
446	    expect(root[SIZE_CHIPS_KEY]).toBeUndefined();
447	    const hoverBlock = (root[HOVER_CAPABLE_QUERY] ?? {}) as Record<string, unknown>;
448	    expect(hoverBlock[HOVER_PRICE_KEY]).toBeUndefined();
449	    expect(hoverBlock[HOVER_SIZE_CHIPS_KEY]).toBeUndefined();
450	    expect(hoverBlock[FOCUS_WITHIN_PRICE_KEY]).toBeUndefined();
451	    expect(hoverBlock[FOCUS_WITHIN_SIZE_CHIPS_KEY]).toBeUndefined();
452	  });
