/**
 * Wishlist card: colour/size attributes and bag are always visible, plus the remove ('x') overlay
 * on the image. Hover to confirm price swaps out for the size-selector — confirmed identical to
 * PLP's own hover reveal via Figma node `40002187:58460` (see index.tsx's module docblock); the
 * SFCC-236 Jira AC text alone does not mention this reveal for Wishlist, so this is worth an
 * explicit second look by whoever eyeballs this story.
 */
export const Wishlist: Story = {
  args: {
    id: 'prod-3',
    variation: 'wishlist',
    name: 'Natura Long Sleeve Linen Mini Dress',
    headingLevel: 'h3',
    href: '/product/123',
    primaryImage: PRIMARY_IMAGE,
    hoverImage: HOVER_IMAGE,
    currentPrice: '$595.00',
